sql.if:

AND (
        UPPER(C.POPU_CODE) LIKE #{keywordLike}
     OR UPPER(C.MNGM_TITL) LIKE #{keywordLike}
    )

mapper.select:

   SELECT /* getPopupContentDtl */

     FROM CT_POPUPX C
LEFT JOIN TB_CODEXD D
       ON D.COMM_CODE = #{popupSituCode}
      AND D.COMD_CODE = C.POPU_SITU
    WHERE C.POPU_SITU = #{popuSitu}
      AND C.POPU_CODE = #{popuCode}

SELECT /* getPopupContentCnt */
       COUNT(1)
  FROM CT_POPUPX
 WHERE POPU_SITU = #{popuSitu}
   AND POPU_CODE = #{popuCode}


SELECT /* getPopupSituCnt */
       COUNT(1)
  FROM TB_CODEXD
 WHERE COMM_CODE = #{popupSituCode}
   AND COMD_CODE = #{popuSitu}
   AND COALESCE(USEE_YSNO, #{yes}) = #{yes}

mapper.insert:
/* setPopupContent */
INSERT INTO CT_POPUPX (
            POPU_SITU
          , POPU_CODE
          , MNGM_TITL
          , CONT_FIRS
          , ENGL_FIRS
          , CONT_SECO
          , ENGL_SECO
          , CONT_THIR
          , ENGL_THIR
          , CONT_FOUR
          , ENGL_FOUR
          , REGI_ADMN
          , REGI_DATE
          , UPDT_ADMN
          , UPDT_DATE
) VALUES (  #{popuSitu}
          , #{popuCode}
          , #{mngmTitl}
          , #{contFirs}
          , #{englFirs}
          , #{contSeco,jdbcType=VARCHAR}
          , #{englSeco,jdbcType=VARCHAR}
          , #{contThir,jdbcType=VARCHAR}
          , #{englThir,jdbcType=VARCHAR}
          , #{contFour,jdbcType=VARCHAR}
          , #{englFour,jdbcType=VARCHAR}
          , #{regiAdmn}
          , CURRENT_TIMESTAMP
          , #{updtAdmn}
          , CURRENT_TIMESTAMP
)

mapper.update:
UPDATE /* uptPopupContent */
       CT_POPUPX
   SET MNGM_TITL = #{mngmTitl}
     , CONT_FIRS = #{contFirs}
     , ENGL_FIRS = #{englFirs}
     , CONT_SECO = #{contSeco,jdbcType=VARCHAR}
     , ENGL_SECO = #{englSeco,jdbcType=VARCHAR}
     , CONT_THIR = #{contThir,jdbcType=VARCHAR}
     , ENGL_THIR = #{englThir,jdbcType=VARCHAR}
     , CONT_FOUR = #{contFour,jdbcType=VARCHAR}
     , ENGL_FOUR = #{englFour,jdbcType=VARCHAR}
     , UPDT_ADMN = #{updtAdmn}
     , UPDT_DATE = CURRENT_TIMESTAMP
 WHERE POPU_SITU = #{popuSitu}
   AND POPU_CODE = #{popuCode}
